RONJ=[dict(q='1970年代に日本の高度経済成長が終わった理由を、国際的な背景にふれて説明せよ。',hint='ニクソン＝ショック・変動相場制・第1次石油危機・狂乱物価・マイナス成長。',points=['1971年のニクソン＝ショックで固定相場制がゆらぎ、1973年に<b>変動相場制</b>に移行して<b>円高</b>が進み、輸出に有利な条件が失われた。','1973年の第4次中東戦争をきっかけに<b>第1次石油危機</b>がおこり、高度成長を支えた<b>安価な原油の安定供給</b>が失われた。','列島改造による投機と原油高が重なって<b>狂乱物価</b>となり、金融引締めでスタグフレーションとなって、1974年に戦後初の<b>マイナス成長</b>となった。']),
dict(q='1990年代の平成不況が長期化した理由を説明せよ。',hint='資産デフレ・不良債権・複合不況・リストラ・金融機関の破綻。',points=['バブル崩壊で株価・地価が暴落し（<b>資産デフレ</b>）、金融機関が大量の<b>不良債権</b>を抱えて金融がゆきづまり、実体経済の不況に波及した（<b>複合不況</b>）。','企業の<b>リストラ</b>で失業が増えて消費が冷えこみ、円高で輸出産業も苦しくなった。','政府・日銀が当初は循環的な不況とみて財政支出と低金利で対応したが効果がなく、住専や北海道拓殖銀行・山一証券などの<b>金融機関の破綻</b>があいついだ。']),
dict(q='冷戦の終結後、日本の安全保障政策がどのように変化したかを説明せよ。',hint='湾岸戦争・PKO協力法・日米安保共同宣言・新ガイドライン・テロ対策特別措置法。',points=['<b>湾岸戦争</b>で資金援助だけでは国際的に評価されず、1992年に<b>PKO協力法</b>を制定して自衛隊の海外派遣を始めた。','1996年の<b>日米安保共同宣言</b>で冷戦後の日米安保体制を再定義し、<b>新ガイドライン</b>と関連法で周辺事態での後方支援を可能にした。','2001年の<b>テロ対策特別措置法</b>、2003年のイラク復興支援特別措置法で活動の範囲を広げ、2015年の<b>安全保障関連法</b>で集団的自衛権の行使を可能にした。'])]
